def generate_cvv_combinations():
    # Generate all 3-digit combinations from 000 to 999
    cvvs = [''.join(combination) for combination in itertools.product('0123456789', repeat=3)]
    return cvvs

def display_combinations_with_flag_check():
    combinations = generate_cvv_combinations()
    for cvv in combinations:
        print(cvv)
        # Check if the cvv matches the flag format
        if 'flag{' in cvv and '}' in cvv:
            print("Potential flag found:", cvv)

if __name__ == "__main__":
    display_combinations_with_flag_check()

import string

def xor_with_key(data: str, key: int) -> str:
    """XOR each character in the given string with a key"""
    return ''.join(chr(ord(char) ^ key) for char in data)

def caesar_cipher(data: str, shift: int) -> str:
    """Apply a Caesar cipher (shift) to the string"""
    result = ''
    for char in data:
        if char.isalpha():
            ascii_offset = ord('A') if char.isupper() else ord('a')
            result += chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
        elif char.isdigit():
            result += chr((ord(char) - ord('0') + shift) % 10 + ord('0'))
        else:
            result += char
    return result

def transform_and_check():
    flag_pattern = "flag{"  # Look for any outputs resembling flag patterns
    keywords = ['CVV']  # Start with 'CVV'
    keywords.extend([f"{i:03}" for i in range(1000)])  # Add all 3-digit CVV combinations

    results = []

    # XOR Transformations
    for key in range(256):  # Possible byte values for XOR keys
        for word in keywords:
            transformed = xor_with_key(word, key)
            if flag_pattern in transformed:
                results.append(("XOR", word, key, transformed))

    # Caesar Cipher (ROT) Transformations
    for shift in range(1, 26):  # Shifts for Caesar cipher
        for word in keywords:
            transformed = caesar_cipher(word, shift)
            if flag_pattern in transformed:
                results.append(("ROT", word, shift, transformed))

    # Print results
    for result in results:
        method, original, param, output = result
        print(f"Method: {method}, Original: {original}, Param: {param}, Output: {output}")

if __name__ == "__main__":
    transform_and_check()

